-- Circuit de reformulation des libellés (audit juridique du 01/10/2026, §6,
-- option C) : propositions de reformulation des libellés de recommandation
-- recopiés quasi mot pour mot de sources autres que la SFAR et la HAS, à
-- valider par un médecin avant toute modification d'une fiche.
--
--   - libelles_reformulation : une ligne par libellé (fiche, chemin dans
--     presentation_json, texte d'origine, proposition, statut) ;
--   - appliquer_reformulation(id, texte) : validateur ou administrateur ;
--     remplace le libellé dans la fiche seulement si le texte d'origine est
--     inchangé (sinon refus) ; le texte validé peut être retouché ;
--   - refuser_reformulation(id) : la proposition est écartée ;
--   - lecture réservée à l'équipe éditoriale ; tout est tracé au journal.
-- Propositions générées le 01/10/2026 (211 libellés) ; chiffres, doses,
-- unités, grades et force de recommandation contrôlés automatiquement.
-- Idempotent.

create table if not exists public.libelles_reformulation (
  id uuid primary key default gen_random_uuid(),
  fiche_key text not null,
  document_id uuid references public.documents(id) on delete cascade,
  chemin text[] not null,
  original_html text not null,
  proposition_html text not null,
  texte_applique text,
  status text not null default 'proposee' check (status in ('proposee', 'appliquee', 'refusee')),
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  unique (fiche_key, chemin)
);
create index if not exists libelles_reformulation_status_idx on public.libelles_reformulation (status, fiche_key);

alter table public.libelles_reformulation enable row level security;
revoke all on public.libelles_reformulation from public, anon, authenticated;
grant select on public.libelles_reformulation to authenticated;
grant all on public.libelles_reformulation to service_role;
drop policy if exists libelles_reformulation_select_equipe on public.libelles_reformulation;
create policy libelles_reformulation_select_equipe on public.libelles_reformulation for select
  to authenticated using (public.has_editorial_role('validateur'));

create or replace function public.appliquer_reformulation(reformulation_id uuid, texte text)
returns text language plpgsql volatile security definer set search_path = public
as $$
declare
  r public.libelles_reformulation;
  actuel text;
  propre text := btrim(coalesce(texte, ''));
begin
  if auth.uid() is null or not public.has_editorial_role('validateur') then
    raise exception 'Réservé aux validateurs' using errcode = '42501';
  end if;
  select * into r from public.libelles_reformulation where id = reformulation_id for update;
  if r.id is null or r.status <> 'proposee' then
    return 'introuvable';
  end if;
  if char_length(propre) < 3 or char_length(propre) > 4000 then
    return 'texte_invalide';
  end if;
  select d.presentation_json #>> (r.chemin || array['html']) into actuel
    from public.documents d where d.id = r.document_id;
  if actuel is distinct from r.original_html then
    return 'fiche_modifiee';
  end if;
  update public.documents d
     set presentation_json = jsonb_set(d.presentation_json, r.chemin || array['html'], to_jsonb(propre))
   where d.id = r.document_id;
  update public.libelles_reformulation
     set status = 'appliquee', texte_applique = propre, decided_by = auth.uid(), decided_at = now()
   where id = r.id;
  insert into public.audit_log (actor_id, action, entity_type, entity_id, before, after)
  values (auth.uid(), 'reformulation_appliquee', 'documents', r.document_id,
          jsonb_build_object('html', r.original_html), jsonb_build_object('html', propre));
  return 'ok';
end;
$$;

create or replace function public.refuser_reformulation(reformulation_id uuid)
returns text language plpgsql volatile security definer set search_path = public
as $$
begin
  if auth.uid() is null or not public.has_editorial_role('validateur') then
    raise exception 'Réservé aux validateurs' using errcode = '42501';
  end if;
  update public.libelles_reformulation
     set status = 'refusee', decided_by = auth.uid(), decided_at = now()
   where id = reformulation_id and status = 'proposee';
  return case when found then 'ok' else 'introuvable' end;
end;
$$;

revoke execute on function public.appliquer_reformulation(uuid, text) from public, anon;
revoke execute on function public.refuser_reformulation(uuid) from public, anon;
grant execute on function public.appliquer_reformulation(uuid, text) to authenticated, service_role;
grant execute on function public.refuser_reformulation(uuid) to authenticated, service_role;

-- Propositions (fiche retrouvée par sa clé ; ignorées si la fiche n'existe pas).
insert into public.libelles_reformulation (fiche_key, document_id, chemin, original_html, proposition_html)
select v.fiche_key, d.id, v.chemin, v.original_html, v.proposition_html
from (values
  ('transfusion_plasma', array['sections','0','items','18','rows','5','0']::text[], 'Plasmathérapie au long cours : peut être nécessaire dans les PTT héréditaires récurrents.', 'Dans les PTT héréditaires qui récidivent, une plasmathérapie prolongée peut s''avérer nécessaire.'),
  ('catheters_veineux_centraux', array['sections','0','items','2','rows','1','1']::text[], 'a — études prospectives, contrôlées, randomisées&nbsp;;&nbsp; b — études non randomisées, comparaisons simultanées ou historiques de cohortes&nbsp;;&nbsp; c — mises au point, revues générales, éditoriaux, séries substantielles de cas publiés dans des revues avec comité de lecture et révisés par des experts extérieurs&nbsp;;&nbsp; d — publications d''opinions publiées dans des journaux ou livres sans comité de lecture.', 'a — essais prospectifs, contrôlés et randomisés ; b — études non randomisées, avec comparaison simultanée ou historique de cohortes ; c — mises au point, revues générales, éditoriaux et séries importantes de cas parues dans des revues à comité de lecture et relues par des experts extérieurs ; d — opinions publiées dans des revues ou ouvrages sans comité de lecture.'),
  ('aod_urgence', array['sections','1','items','18','rows','5','1']::text[], 'Hémorragie intracrânienne et intraspinale ; hémorragie intraoculaire et rétro-orbitaire ; hémothorax, hémo- et rétropéritoine, hémopéricarde ; hématome musculaire profond et/ou syndrome de loge ; hémorragie digestive aiguë ; hémarthrose.', 'Hémorragies intracrânienne ou intraspinale, intraoculaire ou rétro-orbitaire ; hémothorax, hémopéritoine ou rétropéritoine, hémopéricarde ; hématome musculaire profond et/ou syndrome de loge ; saignement digestif aigu ; hémarthrose.'),
  ('insuffisance_analgesie_cesarienne', array['sections','0','items','6','rows','3','1']::text[], 'L''évaluation de l''adéquation du niveau sensitif repose sur la sensation de toucher ± de froid. Un niveau sensitif supérieur bilatéral et symétrique en T6 au toucher ± en T3 au froid est requis (T6 = pointe xiphoïde, T4 = ligne mamelonnaire).', 'Le niveau sensitif s''apprécie au toucher, éventuellement complété par le froid. Il doit atteindre de façon bilatérale et symétrique au moins T6 au toucher, éventuellement T3 au froid (T6 = pointe xiphoïde, T4 = ligne mamelonnaire).'),
  ('insuffisance_analgesie_cesarienne', array['sections','1','items','7','rows','2','1']::text[], 'L''article L 1110-5-3 du Code de la Santé Publique dispose que « toute personne a le droit de recevoir des traitements et des soins visant à soulager sa souffrance […] celle-ci devant être, en toutes circonstances, prévenue, prise en compte, évaluée et traitée ».', 'Selon l''article L 1110-5-3 du Code de la santé publique, chacun a droit à des traitements et soins destinés à soulager sa souffrance, laquelle doit en toutes circonstances être prévenue, prise en compte, évaluée et traitée.'),
  ('ecbu', array['sections','0','items','4','rows','1','0']::text[], 'L''ECBU est la méthode de référence pour dépister une colonisation urinaire.', 'Le dépistage d''une colonisation urinaire repose en référence sur l''ECBU.'),
  ('traumatisme_pelvien', array['sections','1','items','1','rows','1','1']::text[], 'Il est recommandé de considérer la douleur spontanée du pelvis chez un patient conscient comme un signe évocateur de fracture du bassin. Lorsque le patient est inconscient ou choqué, il doit être considéré systématiquement comme suspect d''un traumatisme pelvien.', 'Chez un patient conscient, une douleur pelvienne spontanée est à considérer comme évocatrice d''une fracture du bassin (recommandé). Tout patient inconscient ou en état de choc doit d''emblée être tenu pour suspect de traumatisme pelvien.'),
  ('traumatisme_pelvien', array['sections','1','items','1','rows','3','1']::text[], 'Il est recommandé de mettre en place le plus tôt possible une contention externe du bassin chez tout patient suspect d''un traumatisme pelvien grave.', 'Recommandé : poser une contention pelvienne externe le plus tôt possible chez tout patient suspect de traumatisme pelvien grave.'),
  ('traumatisme_pelvien', array['sections','1','items','1','rows','4','1']::text[], 'Il est probablement recommandé d''utiliser comme contention externe du bassin une ceinture pelvienne, sans qu''un type particulier ne soit recommandé (à l''exclusion de draps noués). Pour avoir une efficacité comparable au C-clamp chirurgical elle doit être positionnée à hauteur des grands trochanters.', 'Probablement recommandé : utiliser une ceinture pelvienne comme contention externe, sans préférence pour un modèle particulier (draps noués exclus). Pour une efficacité proche de celle du C-clamp chirurgical, elle se place au niveau des grands trochanters.'),
  ('traumatisme_pelvien', array['sections','1','items','1','rows','5','1']::text[], 'Il est recommandé de transférer par transport médicalisé tous les patients présentant un traumatisme pelvien grave vers un centre de référence disposant d''un plateau technique spécialisé en première intention.', 'Recommandé : orienter d''emblée tout traumatisé pelvien grave, par transport médicalisé, vers un centre de référence doté d''un plateau technique spécialisé.'),
  ('traumatisme_pelvien', array['sections','2','items','1','rows','1','1']::text[], 'Il est probablement recommandé de réaliser une radiographie de bassin de face dès l''admission si le patient est instable sur le plan hémodynamique ou nécessite des thérapeutiques urgentes pour contrôler les fonctions vitales.', 'Probablement recommandé : radiographie de face du bassin dès l''admission si le patient est hémodynamiquement instable ou requiert des traitements urgents de contrôle des fonctions vitales.'),
  ('traumatisme_pelvien', array['sections','2','items','1','rows','2','1']::text[], 'Il n''est probablement pas recommandé de réaliser une radiographie de bassin de face en dehors d''une instabilité hémodynamique à l''arrivée en salle d''accueil des détresses vitales, la réalisation rapide d''une tomodensitométrie thoraco-abdomino-pelvienne avec injection de produit de contraste pour bilan vasculaire et osseux complet du pelvis étant alors préférée.', 'Probablement non recommandé : radiographie de face du bassin en salle de déchocage chez un patient hémodynamiquement stable ; on lui préfère alors une tomodensitométrie thoraco-abdomino-pelvienne rapide avec injection de produit de contraste, qui fait le bilan vasculaire et osseux complet du pelvis.'),
  ('traumatisme_pelvien', array['sections','2','items','1','rows','3','1']::text[], 'Il est probablement recommandé de réaliser une eFAST échographie chez tous les patients présentant un traumatisme sévère lors de la prise en charge d''un patient suspect d''un traumatisme grave du bassin.', 'Probablement recommandé : échographie eFAST chez tout traumatisé sévère pris en charge pour suspicion de traumatisme grave du bassin.'),
  ('traumatisme_pelvien', array['sections','3','items','1','rows','1','1']::text[], 'Il est recommandé de réaliser une tomodensitométrie thoraco-abdomino-pelvienne avec injection de produit de contraste avant la réalisation d''une artériographie à visée thérapeutique chez un patient victime d''un traumatisme pelvien grave si son état hémodynamique le permet.', 'Recommandé : chez le traumatisé pelvien grave dont l''état hémodynamique le permet, réaliser une tomodensitométrie thoraco-abdomino-pelvienne injectée avant toute artériographie thérapeutique.'),
  ('traumatisme_pelvien', array['sections','3','items','1','rows','2','1']::text[], 'Il n''est probablement pas recommandé de réaliser à titre systématique une imagerie dédiée pour le bas appareil urinaire (opacification de l''urètre et de la vessie) chez un patient traumatisé pelvien grave.', 'Probablement non recommandé : imagerie systématique dédiée du bas appareil urinaire (opacification de l''urètre et de la vessie) chez le traumatisé pelvien grave.'),
  ('traumatisme_pelvien', array['sections','3','items','1','rows','3','1']::text[], 'Il est probablement recommandé de réaliser une opacification rétrograde de l''urètre et de la vessie, couplée idéalement à une TDM pelvienne chez un patient traumatisé pelvien grave présentant des symptômes évocateurs de traumatisme de la vessie (impossibilité d''uriner, hématurie, empâtement sus-pubien douloureux, vessie sur le trajet d''une plaie pénétrante), en particulier avant tout sondage chez l''homme.', 'Probablement recommandé : opacification rétrograde de l''urètre et de la vessie, idéalement associée à une TDM pelvienne, chez le traumatisé pelvien grave présentant des signes évocateurs de lésion vésicale (impossibilité d''uriner, hématurie, empâtement sus-pubien douloureux, vessie sur le trajet d''une plaie pénétrante), notamment avant tout sondage chez l''homme.'),
  ('traumatisme_pelvien', array['sections','4','items','1','rows','1','1']::text[], 'Il est probablement recommandé de considérer comme critères anatomoradiologiques de traumatisme pelvien grave : une fracture du pelvis instable selon les classifications de Young-Burgess et de Tile, en particulier les fractures dites « open book » et les ruptures de l''anneau pelvien avec atteinte postérieure ; l''existence d''une extravasation de produit de contraste au temps artériel observée sur une angioscanographie ou une tomodensitométrie.', 'Probablement recommandé : retenir comme critères anatomoradiologiques de gravité d''un traumatisme pelvien une fracture instable selon les classifications de Young-Burgess et de Tile (notamment fractures « open book » et ruptures de l''anneau pelvien avec atteinte postérieure), ou une extravasation de produit de contraste au temps artériel en angioscanographie ou tomodensitométrie.'),
  ('traumatisme_pelvien', array['sections','5','items','1','rows','2','1']::text[], 'Il est recommandé que le délai entre l''admission hospitalière et le geste d''hémostase ne dépasse pas 60 minutes, quelle que soit la technique utilisée.', 'Recommandé : quelle que soit la technique, le délai entre l''admission à l''hôpital et le geste d''hémostase ne doit pas excéder 60 minutes.'),
  ('traumatisme_pelvien', array['sections','5','items','4','rows','1','1']::text[], 'Les experts recommandent de réaliser une embolisation non sélective par un abord fémoral commun chez les patients instables, chez les patients stables présentant de nombreuses cibles identifiées en TDM ou à l''angiographie et en cas d''échec de l''embolisation sélective.', 'Selon les experts, l''embolisation non sélective par abord fémoral commun est recommandée chez le patient instable, chez le patient stable ayant de multiples cibles en TDM ou en angiographie, et après échec d''une embolisation sélective.'),
  ('traumatisme_pelvien', array['sections','5','items','4','rows','2','1']::text[], 'Il n''est probablement pas recommandé de réaliser un contrôle artériographique systématique chez tous les patients ayant bénéficié d''une artério-embolisation à la phase initiale de prise en charge d''un traumatisme pelvien grave.', 'Probablement non recommandé : contrôle artériographique systématique après artério-embolisation réalisée à la phase initiale d''un traumatisme pelvien grave.'),
  ('traumatisme_pelvien', array['sections','6','items','1','rows','1','1']::text[], 'Il est probablement recommandé d''avoir recours à un tamponnement pelvien pré-péritonéal chirurgical en association avec une fixation externe du bassin en cas d''instabilité hémodynamique majeure rendant impossible le transfert du patient au scanner et/ou en embolisation, ou la réalisation d''une artériographie-embolisation dans un délai de 60 minutes à partir du diagnostic.', 'Probablement recommandé : associer un tamponnement pelvien pré-péritonéal chirurgical à une fixation externe du bassin lorsque l''instabilité hémodynamique majeure empêche le transfert au scanner et/ou en embolisation, ou qu''une artériographie-embolisation ne peut être faite dans les 60 minutes suivant le diagnostic.'),
  ('traumatisme_pelvien', array['sections','6','items','1','rows','2','1']::text[], 'Il est recommandé de réaliser une fixation externe précoce du bassin chez les patients présentant un traumatisme pelvien grave avec instabilité hémodynamique pour limiter l''expansion de l''hématome pelvien. La fixation externe peut être réalisée par un Clamp de Ganz ou un fixateur externe antérieur.', 'Recommandé : fixation externe précoce du bassin chez le traumatisé pelvien grave hémodynamiquement instable, afin de limiter l''extension de l''hématome pelvien. Elle peut utiliser un clamp de Ganz ou un fixateur externe antérieur.'),
  ('traumatisme_pelvien', array['sections','7','items','1','rows','2','1']::text[], 'Il est recommandé de considérer comme objectifs initiaux de la prise en charge des traumatismes pelviens graves ouverts le contrôle de l''hémorragie et de la contamination périnéale.', 'Recommandé : dans un traumatisme pelvien grave ouvert, les premiers objectifs sont de contrôler l''hémorragie et la contamination périnéale.'),
  ('tih', array['sections','1','items','14','rows','1','1']::text[], 'En cas de suspicion, il est proposé de rechercher le plus rapidement possible des <b>anticorps anti-FP4</b> si la probabilité clinique de TIH est <b>intermédiaire ou élevée</b>.', 'Proposé : devant une suspicion de TIH de probabilité clinique <b>intermédiaire ou élevée</b>, rechercher au plus vite les <b>anticorps anti-FP4</b>.'),
  ('tih', array['sections','1','items','46','rows','4','1']::text[], 'Il est proposé de <b>ne pas mettre de filtre cave</b> à la phase aiguë d''une TIH.', 'Proposé : ne pas poser de <b>filtre cave</b> pendant la phase aiguë d''une TIH.'),
  ('transport_intrahospitalier', array['sections','0','items','4','rows','5','1']::text[], 'Un EIG est une complication directement liée aux soins, pouvant entraîner un risque vital, une prolongation de séjour, la nécessité de gestes invasifs et des séquelles invalidantes.', 'Un EIG est une complication en lien direct avec les soins, susceptible d''engager le pronostic vital, d''allonger le séjour, d''imposer des gestes invasifs ou de laisser des séquelles invalidantes.'),
  ('transport_intrahospitalier', array['sections','0','items','4','rows','19','1']::text[], 'Il faut faire un signalement des EI pouvant survenir pendant le TIH, qui devront ensuite être analysés.', 'Les EI survenant au cours du TIH doivent être signalés puis analysés.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','4','1']::text[], 'Chez le patient non ventilé, la fréquence ventilatoire doit être surveillée à intervalle régulier, au mieux de façon monitorée.', 'Chez le patient non ventilé, surveiller régulièrement la fréquence respiratoire, idéalement par monitorage.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','11','1']::text[], 'Les moyens de monitorage doivent être adaptés au type de transport, à la sévérité du patient et aux thérapeutiques utilisées, selon une procédure écrite.', 'Le monitorage est adapté, selon une procédure écrite, au type de transport, à la gravité du patient et aux traitements en cours.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','13','1']::text[], 'Le réglage des consignes machine du ventilateur de transport doit permettre les mêmes paramètres de ventilation, y compris les modes non invasifs.', 'Le ventilateur de transport doit pouvoir reproduire les mêmes réglages ventilatoires, modes non invasifs compris.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','19','1']::text[], 'L''interface du ventilateur de transport ne doit pas permettre de déréglages accidentels des consignes machine.', 'L''interface du ventilateur de transport ne doit pas permettre de modifier les consignes par inadvertance.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','22','1']::text[], 'Le ventilateur de transport doit être stocké dans un endroit accessible connu des utilisateurs, avec ses accessoires (circuit complet avec ECH et raccord annelé, tuyau d''alimentation en gaz médicaux).', 'Ranger le ventilateur de transport dans un lieu accessible et connu de tous les utilisateurs, avec ses accessoires (circuit complet comprenant ECH et raccord annelé, tuyau d''arrivée des gaz médicaux).'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','23','1']::text[], 'Le circuit utilisé doit être en accord avec les recommandations du fabricant.', 'Le circuit doit être conforme aux recommandations du fabricant.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','24','1']::text[], 'Lorsque le ventilateur le nécessite, il doit être étalonné en fonction du type de circuit utilisé.', 'Si le ventilateur l''exige, l''étalonner selon le type de circuit employé.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','28','1']::text[], 'Une auto-extubation doit pouvoir être identifiée immédiatement par le monitorage de la capnographie et/ou de la spirométrie expiratoire.', 'Le monitorage de la capnographie et/ou de la spirométrie expiratoire doit permettre de repérer immédiatement une auto-extubation.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','30','1']::text[], 'En mode VS-AI-PEP (invasive ou non), le ventilateur de transport doit avoir les caractéristiques générales requises (performances, monitorage) pour garantir la qualité de ventilation.', 'En VS-AI-PEP, invasive ou non, le ventilateur de transport doit présenter les performances et le monitorage nécessaires à une ventilation de qualité.'),
  ('transport_intrahospitalier', array['sections','0','items','6','rows','40','1']::text[], 'Après utilisation, le ventilateur doit être nettoyé et désinfecté selon une procédure écrite et tracée.', 'Après chaque usage, nettoyer et désinfecter le ventilateur selon une procédure écrite et tracée.'),
  ('transport_intrahospitalier', array['sections','0','items','8','rows','8','1']::text[], 'La position optimale du patient en réanimation doit être poursuivie pendant le TIH.', 'Pendant le TIH, maintenir la position optimale prescrite en réanimation.'),
  ('transport_intrahospitalier', array['sections','0','items','8','rows','9','1']::text[], 'Il faut anticiper, évaluer et traiter les douleurs pouvant être induites par le TIH et/ou les soins qui seront réalisés.', 'Anticiper, évaluer et traiter la douleur que peuvent provoquer le TIH et/ou les soins prévus.'),
  ('transport_intrahospitalier', array['sections','0','items','8','rows','17','1']::text[], 'La pression du ballonnet du dispositif intratrachéal doit être vérifiée avant et au retour du TIH.', 'Vérifier la pression du ballonnet de la sonde intratrachéale avant le TIH et au retour.'),
  ('transport_intrahospitalier', array['sections','0','items','10','rows','2','1']::text[], 'Il faut une formation au transport pédiatrique, initiale et régulière, du personnel médical et paramédical assurant les TIH des enfants de moins de 15 kg.', 'Les équipes médicales et paramédicales qui transportent des enfants de moins de 15 kg doivent recevoir une formation initiale et continue au transport pédiatrique.'),
  ('transport_intrahospitalier', array['sections','0','items','10','rows','4','1']::text[], 'L''appréciation du risque et les modalités liées au TIH sont sous la responsabilité du médecin senior en charge du patient.', 'L''évaluation du risque et l''organisation du TIH relèvent du médecin senior responsable du patient.'),
  ('transport_intrahospitalier', array['sections','0','items','12','rows','6','1']::text[], 'Une traçabilité imprimable des données du monitorage au cours du TIH est souhaitable.', 'Il est souhaitable de pouvoir imprimer et tracer les données de monitorage recueillies pendant le TIH.'),
  ('civd', array['sections','1','items','10','rows','1','1']::text[], 'L''association de polymorphismes génétiques avec la CIVD reste du domaine de la recherche.', 'Le lien entre polymorphismes génétiques et CIVD relève encore de la recherche.'),
  ('asthme_aigu_grave', array['sections','1','items','1','rows','2','1']::text[], 'La voie inhalée est prioritaire dans tous les cas, en raison de son efficacité liée à la pénétration locale et de ses effets systémiques limités.', 'La voie inhalée est toujours privilégiée : elle agit localement et limite les effets systémiques.'),
  ('asthme_aigu_grave', array['sections','1','items','1','rows','7','1']::text[], 'Puis une nébulisation de 5 mg toutes les 3 h (ou 2,5 mg/h) pendant les six heures suivantes.', 'Ensuite, nébuliser 5 mg toutes les 3 h (ou 2,5 mg/h) durant les six heures suivantes.'),
  ('mal_epileptique', array['sections','1','items','1','2','rows','1','1']::text[], 'L''EME est défini, de façon générale, par des crises continues ou par la succession de crises sans amélioration de la conscience sur une période de 30 minutes.', 'On parle d''EME devant des crises continues, ou des crises successives sans retour à la conscience, pendant 30 minutes.'),
  ('mal_epileptique', array['sections','1','items','1','2','rows','4','1']::text[], 'Les crises sérielles avec récupération de la conscience antérieure entre les crises peuvent évoluer vers un état de mal mais ne rentrent pas dans la définition de celui-ci.', 'Des crises sérielles entre lesquelles le patient retrouve sa conscience antérieure peuvent évoluer vers un état de mal, mais ne répondent pas à sa définition.'),
  ('mal_epileptique', array['sections','1','items','2','2','rows','1','1']::text[], 'On distingue sur un plan clinique les EME convulsifs, dont le diagnostic repose sur les seules données cliniques, des EME non convulsifs, dont le diagnostic plus difficile nécessite la réalisation d''un électroencéphalogramme (EEG).', 'Cliniquement, on oppose les EME convulsifs, diagnostiqués sur la seule clinique, aux EME non convulsifs, plus difficiles à reconnaître et qui exigent un électroencéphalogramme (EEG).'),
  ('mal_epileptique', array['sections','2','items','6','rows','2','1']::text[], 'L''EEG lors d''une encéphalopathie postanoxique montre des anomalies variées, en particulier des pointes périodiques généralisées qui ne doivent pas faire évoquer des crises voire un état de mal. Des myoclonies non épileptiques peuvent être associées ou non à ces anomalies EEG.', 'Après anoxie, l''EEG peut montrer des anomalies diverses, notamment des pointes périodiques généralisées, à ne pas interpréter comme des crises ou un état de mal. Des myoclonies non épileptiques peuvent ou non les accompagner.'),
  ('mal_epileptique', array['sections','3','items','0','2','rows','2','1']::text[], 'Celui-ci devrait idéalement être disponible 24 h/24 pour le diagnostic et le suivi des formes graves.', 'L''idéal est un EEG accessible 24 h/24 pour diagnostiquer et suivre les formes graves.'),
  ('mal_epileptique', array['sections','3','items','2','rows','1','1']::text[], 'Un EEG en urgence est indiqué dans les EME convulsifs généralisés, sans en retarder la prise en charge thérapeutique initiale.', 'Dans un EME convulsif généralisé, l''EEG est indiqué en urgence, sans retarder le traitement initial.'),
  ('mal_epileptique', array['sections','3','items','3','rows','2','1']::text[], 'Un enregistrement EEG standard avec au moins huit voies, et idéalement 21 voies, durant au moins 20 minutes, et au mieux 30 minutes, est l''examen de référence.', 'L''examen de référence est un EEG standard d''au moins huit voies (idéalement 21), d''une durée d''au moins 20 minutes (au mieux 30).'),
  ('mal_epileptique', array['sections','4','items','0','2','rows','1','1']::text[], 'La recherche étiologique doit être effectuée rapidement, sans retarder ni la mise en œuvre du traitement antiépileptique ni les manœuvres de réanimation.', 'Rechercher rapidement la cause, sans retarder le traitement antiépileptique ni la réanimation.'),
  ('mal_epileptique', array['sections','4','items','1','rows','6','1']::text[], 'Plus rarement, car dans ces cas le patient peut déjà avoir présenté des crises : les lésions cérébrales subaiguës évolutives (comme les tumeurs, la toxoplasmose cérébrale), les affections dégénératives.', 'Causes plus rares, le patient ayant alors souvent déjà présenté des crises : lésions cérébrales subaiguës évolutives (tumeurs, toxoplasmose cérébrale par exemple) et affections dégénératives.'),
  ('mal_epileptique', array['sections','4','items','6','rows','3','1']::text[], 'En l''absence de cause évidente à un EME convulsif chez un nourrisson, une injection de pyridoxine doit être proposée (50 à 100 mg/kg) en milieu de réanimation sous monitorage et enregistrement EEG.', 'Chez le nourrisson en EME convulsif sans cause évidente, proposer une injection de pyridoxine (50 à 100 mg/kg) en réanimation, sous monitorage et enregistrement EEG.'),
  ('mal_epileptique', array['sections','4','items','8','2','rows','4','1']::text[], 'Par rapport à des crises épileptiques inaugurales, un EME de novo augmente le risque de développer une épilepsie.', 'Comparé à des crises inaugurales, un EME de novo accroît le risque d''évolution vers une épilepsie.'),
  ('mal_epileptique', array['sections','4','items','10','rows','2','1']::text[], 'Les mesures de prise en charge immédiate comportent : la mise en position latérale de sécurité, le maintien de la liberté des voies aériennes supérieures, une oxygénation avec pour objectif une SpO2 supérieure ou égale à 95 %, la mise en place d''une voie veineuse périphérique avec perfusion de sérum physiologique, la mesure de la glycémie capillaire et la correction d''une éventuelle hypoglycémie.', 'Mesures immédiates : position latérale de sécurité ; liberté des voies aériennes supérieures ; oxygénation visant une SpO2 d''au moins 95 % ; voie veineuse périphérique avec perfusion de sérum physiologique ; glycémie capillaire et correction d''une hypoglycémie éventuelle.'),
  ('mal_epileptique', array['sections','4','items','10','rows','4','1']::text[], 'En préhospitalier, la sécurité du transport autorise un délai plus court de recours à la ventilation mécanique.', 'En préhospitalier, la sécurité du transport justifie de recourir plus tôt à la ventilation mécanique.'),
  ('mal_epileptique', array['sections','4','items','11','rows','2','1']::text[], 'Il est recommandé de maintenir une pression artérielle moyenne entre 70 et 90 mmHg.', 'Recommandé : pression artérielle moyenne maintenue entre 70 et 90 mmHg.'),
  ('mal_epileptique', array['sections','5','items','2','rows','2','1']::text[], 'Dans tous les cas, un monitorage de la fréquence cardiaque et respiratoire, de la pression artérielle et de la saturation en oxygène est mis en place.', 'Toujours monitorer fréquences cardiaque et respiratoire, pression artérielle et saturation en oxygène.'),
  ('mal_epileptique', array['sections','5','items','2','rows','4','1']::text[], 'Quand le patient est pris en charge entre cinq et 30 minutes après le début des convulsions, une benzodiazépine en monothérapie est recommandée par voie intraveineuse lente (en une à deux minutes au moins). En cas de persistance des convulsions au bout de cinq minutes, on procédera à une seconde injection de la même benzodiazépine, à la même dose, associée à un autre médicament antiépileptique en intraveineux.', 'Patient pris en charge entre cinq et 30 minutes après le début des convulsions : benzodiazépine seule recommandée, en intraveineux lent (sur une à deux minutes au moins). Si les convulsions persistent au bout de cinq minutes, répéter la même benzodiazépine à la même dose en y associant un autre antiépileptique intraveineux.'),
  ('mal_epileptique', array['sections','5','items','4','rows','5','1']::text[], '<b>L''attitude qui consiste à administrer un complément de dose</b> de phénytoïne, fosphénytoïne ou phénobarbital <b>ne repose sur aucune donnée clinique validée.</b>', '<b>Administrer un complément de dose</b> de phénytoïne, de fosphénytoïne ou de phénobarbital <b>n''est fondé sur aucune donnée clinique validée.</b>'),
  ('mal_epileptique', array['sections','5','items','6','rows','1','1']::text[], 'Un relais par benzodiazépines par voie entérale (clobazam : 5 à 10 mg × 3 ou clonazépam : 1 à 2 mg × 3) ou parentérale discontinue est indispensable. Ce relais doit être immédiat si l''EME a été contrôlé par une seule dose de diazépam ou de midazolam, en raison du risque de récidive à court terme.', 'Un relais par benzodiazépine, par voie entérale (clobazam 5 à 10 mg × 3 ou clonazépam 1 à 2 mg × 3) ou parentérale discontinue, est indispensable. Il doit être immédiat si une seule dose de diazépam ou de midazolam a suffi à contrôler l''EME, car le risque de récidive précoce est élevé.'),
  ('mal_epileptique', array['sections','5','items','9','rows','2','1']::text[], 'La posologie du clonazépam est de 0,015 mg/kg, celle du diazépam de 0,15 mg/kg.', 'Posologie : clonazépam 0,015 mg/kg ; diazépam 0,15 mg/kg.'),
  ('mal_epileptique', array['sections','5','items','9','rows','4','1']::text[], 'Lorsque l''administration de benzodiazépines par voie intraveineuse est impossible, le midazolam en intramusculaire (0,15 mg/kg) ou par voie buccale (0,3 mg/kg) peut être employé.', 'Si la voie intraveineuse est impossible, le midazolam peut être donné en intramusculaire (0,15 mg/kg) ou par voie buccale (0,3 mg/kg).'),
  ('mal_epileptique', array['sections','5','items','11','rows','1','1']::text[], 'Le phénobarbital est utilisé en intraveineux à la posologie de 15 mg/kg à un débit de perfusion maximum de 100 mg/min.', 'Phénobarbital intraveineux : 15 mg/kg, débit maximal de 100 mg/min.'),
  ('mal_epileptique', array['sections','5','items','13','rows','1','1']::text[], 'La fosphénytoïne (ampoules de 500 mg en équivalents de phénytoïne sodique) est utilisée à la posologie de 20 mg/kg en équivalents de phénytoïne sodique, à un débit de perfusion maximum de 150 mg/min. Ce débit pourra être réduit chez des patients considérés comme fragiles (sujet âgé, coronarien).', 'Fosphénytoïne (ampoules de 500 mg en équivalents de phénytoïne sodique) : 20 mg/kg en équivalents de phénytoïne sodique, débit maximal de 150 mg/min, à réduire chez le patient fragile (sujet âgé, coronarien).'),
  ('mal_epileptique', array['sections','5','items','13','rows','2','1']::text[], 'La phénytoïne (ampoules de 250 mg) est utilisée à la posologie de 20 mg/kg avec un débit de perfusion maximum de 50 mg/min. Ce débit pourra être réduit chez des patients considérés comme fragiles (sujet âgé, coronarien).', 'Phénytoïne (ampoules de 250 mg) : 20 mg/kg, débit maximal de 50 mg/min, à réduire chez le patient fragile (sujet âgé, coronarien).'),
  ('mal_epileptique', array['sections','5','items','13','rows','5','1']::text[], 'La phénytoïne et la fosphénytoïne, bien qu''administrées à un débit différent (trois fois plus rapide pour la fosphénytoïne), agissent dans le même délai. En pratique, leur pleine efficacité ne pourra être évaluée que 30 minutes après le début de la perfusion.', 'Bien que la fosphénytoïne se perfuse trois fois plus vite que la phénytoïne, les deux agissent dans le même délai : leur pleine efficacité ne s''apprécie que 30 minutes après le début de la perfusion.'),
  ('mal_epileptique', array['sections','5','items','17','rows','3','1']::text[], 'Lors des intoxications par médicaments ou substances illicites, les benzodiazépines puis les barbituriques (si nécessaires) sont conseillés.', 'Dans les intoxications médicamenteuses ou par substances illicites, on conseille les benzodiazépines, puis si besoin les barbituriques.'),
  ('mal_epileptique', array['sections','5','items','19','rows','3','1']::text[], 'Le phénobarbital est utilisé par voie veineuse à la posologie de 15 à 20 mg/kg avec un débit de perfusion maximum de 100 mg/min.', 'Phénobarbital intraveineux : 15 à 20 mg/kg, débit maximal de 100 mg/min.'),
  ('mal_epileptique', array['sections','5','items','19','rows','4','1']::text[], 'La dose de charge de phénytoïne par voie veineuse est de 20 mg/kg (maximum 1 g) sans dépasser un débit de perfusion de 1 mg/kg par minute.', 'Dose de charge de phénytoïne intraveineuse : 20 mg/kg (1 g au maximum), débit limité à 1 mg/kg par minute.'),
  ('mal_epileptique', array['sections','6','items','4','rows','7','1']::text[], 'L''utilisation du propofol, particulièrement à des fortes posologies et au-delà de 48 heures, impose une détermination au moins biquotidienne des lactates, des triglycérides et des enzymes musculaires afin de dépister rapidement un « SPP » qui implique son arrêt immédiat.', 'Sous propofol, surtout à forte dose et au-delà de 48 heures, doser au moins deux fois par jour lactates, triglycérides et enzymes musculaires pour repérer tôt un « SPP », qui impose l''arrêt immédiat du médicament.'),
  ('mal_epileptique', array['sections','6','items','8','rows','3','1']::text[], 'La facilité d''emploi du midazolam (hydrosoluble, demi-vie courte) doit être pondérée par la plus grande fréquence de récidives des convulsions observée avec ce médicament.', 'Le midazolam est simple d''emploi (hydrosoluble, demi-vie courte), mais il expose à davantage de récidives convulsives.'),
  ('mal_epileptique', array['sections','7','items','1','rows','3','1']::text[], 'L''enquête étiologique des états d''absence de novo du sujet âgé doit comporter en premier lieu la recherche de facteurs toxiques et/ou métaboliques comme un sevrage en benzodiazépines ou une imprégnation chronique en médicaments psychotropes.', 'Devant un état d''absence de novo chez le sujet âgé, chercher d''abord une cause toxique et/ou métabolique, par exemple un sevrage en benzodiazépines ou une imprégnation chronique par des psychotropes.'),
  ('mal_epileptique', array['sections','7','items','1','rows','6','1']::text[], 'La résistance aux benzodiazépines concerne essentiellement les états de mal partiels non convulsifs. Une approche graduelle doit être privilégiée. La phénytoïne ou la fosphénytoïne semblent être les molécules de choix.', 'La résistance aux benzodiazépines touche surtout les états de mal partiels non convulsifs. Une stratégie progressive est à privilégier, la phénytoïne ou la fosphénytoïne paraissant les molécules les plus adaptées.'),
  ('mal_epileptique', array['sections','7','items','4','rows','1','1']::text[], 'La mise en place de protocoles dans les diverses structures amenées à prendre en charge des EME est recommandée.', 'Recommandé : chaque structure susceptible de prendre en charge des EME doit disposer de protocoles.'),
  ('mal_epileptique', array['sections','7','items','4','rows','2','1']::text[], 'Ces recommandations, établies début 2008, devront être réactualisées dans un délai maximum de trois ans.', 'Ces recommandations, rédigées début 2008, sont à actualiser dans un délai de trois ans au plus.'),
  ('securisation_proc', array['sections','0','items','5','rows','4','1']::text[], 'Un événement indésirable <b>patient</b> est une complication directement liée aux soins et non à la pathologie sous-jacente du patient.', 'Un événement indésirable <b>patient</b> est une complication causée par les soins eux-mêmes, et non par la maladie sous-jacente.'),
  ('securisation_proc', array['sections','0','items','7','rows','2','1']::text[], 'Les erreurs médicales et les EI patients doivent être classés en fonction de leur gravité.', 'Erreurs médicales et EI patients sont à classer selon leur gravité.'),
  ('securisation_proc', array['sections','0','items','7','rows','3','1']::text[], 'La standardisation de la méthode de recueil des erreurs médicales et des événements indésirables patients est nécessaire.', 'Le recueil des erreurs médicales et des événements indésirables patients doit suivre une méthode standardisée.'),
  ('securisation_proc', array['sections','0','items','7','rows','4','1']::text[], 'Quelle que soit la méthode, il est recommandé que ce recueil soit non punitif, confidentiel et indépendant.', 'Recommandé : quelle que soit la méthode, un recueil non punitif, confidentiel et indépendant.'),
  ('securisation_proc', array['sections','0','items','7','rows','5','1']::text[], 'Le recueil régulier par la déclaration volontaire, bien que source de biais, permet de développer une culture sécurité.', 'Malgré ses biais, la déclaration volontaire régulière contribue à développer une culture de sécurité.'),
  ('securisation_proc', array['sections','0','items','7','rows','7','1']::text[], 'Il est important de pouvoir identifier indépendamment les erreurs des EI patients.', 'Il importe de pouvoir distinguer les erreurs des EI patients.'),
  ('securisation_proc', array['sections','0','items','9','rows','2','1']::text[], 'Le service de réanimation doit pouvoir disposer de résultats biologiques fiables, obtenus rapidement et dont la traçabilité est assurée (pneumatique, biologie délocalisée).', 'La réanimation doit obtenir rapidement des résultats biologiques fiables et tracés (pneumatique, biologie délocalisée).'),
  ('securisation_proc', array['sections','0','items','9','rows','6','1']::text[], 'L''informatisation du dossier médical et de la prescription doit être développée.', 'Le dossier médical et les prescriptions doivent être davantage informatisés.'),
  ('securisation_proc', array['sections','0','items','9','rows','13','1']::text[], 'Les compétences médicales et paramédicales doivent être identiques en réanimation et en USC.', 'Réanimation et USC requièrent les mêmes compétences médicales et paramédicales.'),
  ('securisation_proc', array['sections','0','items','9','rows','16','1']::text[], 'Il existe un programme de formation dans le service concernant les internes et les médecins de l''équipe.', 'Le service dispose d''un programme de formation destiné aux internes et aux médecins de l''équipe.'),
  ('securisation_proc', array['sections','0','items','9','rows','19','1']::text[], 'Une attention particulière doit être portée sur les équipes de nuit, qui doivent bénéficier soit de formations spécifiques, soit de périodes de rotation de jour.', 'Une vigilance particulière s''impose pour les équipes de nuit, qui doivent bénéficier de formations dédiées ou de périodes de travail de jour en alternance.'),
  ('securisation_proc', array['sections','0','items','9','rows','30','1']::text[], 'Le service dispose d''une méthode de recueil des EI ; chaque service détermine, a priori, quels EI il va surveiller à partir de quels indicateurs et avec quel objectif.', 'Le service dispose d''une méthode de recueil des EI : chacun définit à l''avance les EI qu''il surveille, les indicateurs utilisés et l''objectif poursuivi.'),
  ('securisation_proc', array['sections','0','items','11','rows','4','1']::text[], 'Les différents acteurs intervenant dans la gestion des DM doivent être : un référent biomédical ingénieur par service (ou pôle) et/ou par type de matériel, un référent médical par service ou pôle, enfin un référent paramédical et/ou un technicien délocalisé par service ou pôle.', 'La gestion des DM mobilise : un ingénieur biomédical référent par service (ou pôle) et/ou par type de matériel ; un médecin référent par service ou pôle ; un référent paramédical et/ou un technicien délocalisé par service ou pôle.'),
  ('securisation_proc', array['sections','0','items','11','rows','5','1']::text[], 'Il est recommandé de mettre en place une gestion informatisée du parc des DM.', 'Recommandé : informatiser la gestion du parc de DM.'),
  ('securisation_proc', array['sections','0','items','11','rows','7','1']::text[], 'Le cahier des charges définissant précisément le besoin qualitatif et quantitatif doit être établi en collaboration entre services cliniques et services biomédicaux.', 'Services cliniques et biomédicaux rédigent ensemble le cahier des charges, qui précise les besoins qualitatifs et quantitatifs.'),
  ('securisation_proc', array['sections','0','items','11','rows','8','1']::text[], 'Il faut prendre en compte des éléments tels que : durée de garantie, contrat de maintenance, proximité et disponibilité du service après-vente.', 'Tenir compte notamment de la durée de garantie, du contrat de maintenance et de la proximité et disponibilité du service après-vente.'),
  ('securisation_proc', array['sections','0','items','11','rows','9','1']::text[], 'Les certificats de conformité aux textes réglementaires applicables à la classe du dispositif doivent être exigés.', 'Exiger les certificats de conformité à la réglementation applicable à la classe du dispositif.'),
  ('securisation_proc', array['sections','0','items','11','rows','11','1']::text[], 'En cas de prêt de matériel, une fiche de mise à disposition doit être validée et signée par la société, les services cliniques et biomédicaux.', 'Tout prêt de matériel fait l''objet d''une fiche de mise à disposition validée et signée par la société, les services cliniques et le service biomédical.'),
  ('securisation_proc', array['sections','0','items','11','rows','17','1']::text[], 'Si des check-lists de contrôle sont prévues par le constructeur et intégrées au logiciel du matériel, il faut les respecter et les compléter éventuellement par les check-lists locales.', 'Lorsque le fabricant prévoit des check-lists de contrôle intégrées au logiciel, les appliquer et, si besoin, les compléter par des check-lists locales.'),
  ('securisation_proc', array['sections','0','items','11','rows','21','1']::text[], 'Il est recommandé d''organiser des formations régulièrement pour les utilisateurs en cas de renouvellement des personnels, en cas de fréquence anormale du nombre de défauts utilisateurs ou lors de mise à niveau des matériels.', 'Recommandé : former régulièrement les utilisateurs, notamment lors du renouvellement des équipes, en cas de défauts d''utilisation anormalement fréquents ou lors d''une mise à niveau du matériel.'),
  ('securisation_proc', array['sections','0','items','13','rows','4','1']::text[], 'Deux opérateurs (deux médecins ou un médecin et une infirmière) doivent être présents systématiquement au moment de l''intubation.', 'L''intubation se fait toujours à deux opérateurs (deux médecins, ou un médecin et une infirmière).'),
  ('securisation_proc', array['sections','0','items','13','rows','10','1']::text[], 'Les paramètres de la ventilation mécanique doivent être réadaptés à distance de l''intubation.', 'Réajuster les réglages de la ventilation mécanique à distance de l''intubation.'),
  ('securisation_proc', array['sections','0','items','13','rows','12','1']::text[], 'Si la technique percutanée a été choisie, un fibroscope bronchique doit être utilisé.', 'En cas de technique percutanée, recourir à un fibroscope bronchique.'),
  ('securisation_proc', array['sections','0','items','13','rows','20','1']::text[], 'Le processus de sevrage doit être envisagé aussitôt que possible dans la prise en charge d''une IRA.', 'Dans une IRA, penser au sevrage dès que possible au cours de la prise en charge.'),
  ('securisation_proc', array['sections','0','items','13','rows','29','1']::text[], 'Il peut être utile de mettre en place des protocoles de sevrage.', 'Des protocoles de sevrage peuvent être utiles.'),
  ('securisation_proc', array['sections','0','items','13','rows','31','1']::text[], 'Avant d''envisager une extubation, il faut évaluer la capacité du patient à tousser et à évacuer ses sécrétions.', 'Avant toute extubation, vérifier que le patient tousse efficacement et évacue ses sécrétions.'),
  ('securisation_proc', array['sections','0','items','13','rows','39','1']::text[], 'La maîtrise de la VNI doit représenter un objectif de formation théorique et pratique des personnels médicaux et paramédicaux au sein des services de réanimation.', 'La VNI doit faire partie de la formation théorique et pratique des équipes médicales et paramédicales de réanimation.'),
  ('securisation_proc', array['sections','0','items','13','rows','42','1']::text[], 'Le matériel de VNI disponible (masques, ventilateurs, humidificateurs) doit être adapté à la pathologie et à la gravité des patients pris en charge.', 'Masques, ventilateurs et humidificateurs de VNI doivent être adaptés à la pathologie et à la gravité des patients.'),
  ('securisation_proc', array['sections','0','items','13','rows','45','1']::text[], 'Les risques d''échec de la VNI doivent imposer une surveillance initiale rapprochée au cours des premières heures pour juger de la réponse à la technique.', 'Du fait du risque d''échec, la VNI impose une surveillance étroite dans les premières heures afin d''évaluer la réponse.'),
  ('securisation_proc', array['sections','0','items','15','rows','2','1']::text[], 'Les médicaments vasoactifs doivent être administrés par voie intraveineuse et de façon continue grâce à une seringue pour perfusion continue.', 'Les vasoactifs s''administrent par voie intraveineuse, en continu, au pousse-seringue.'),
  ('securisation_proc', array['sections','0','items','15','rows','4','1']::text[], 'L''utilisation de pompes de perfusion munies de logiciels permettant le relais automatique des seringues contenant une drogue vasoactive doit être privilégiée.', 'Privilégier les pousse-seringues capables d''assurer automatiquement le relais des seringues de vasoactifs.'),
  ('securisation_proc', array['sections','0','items','15','rows','13','1']::text[], 'Un cathéter artériel ne doit pas être posé sur une artère terminale (artère humérale).', 'Ne pas poser de cathéter artériel sur une artère terminale (artère humérale).'),
  ('securisation_proc', array['sections','0','items','15','rows','24','1']::text[], 'Le repérage ultrasonographique peut améliorer le taux de succès du cathétérisme veineux, surtout pour la voie jugulaire interne, sans augmenter le temps de cathétérisme.', 'Le guidage échographique peut augmenter le taux de réussite de la pose d''un cathéter veineux, notamment jugulaire interne, sans allonger la durée du geste.'),
  ('securisation_proc', array['sections','0','items','15','rows','29','1']::text[], 'Lors de l''introduction du cathéter dans les cavités cardiaques, une surveillance permanente du rythme doit être effectuée afin de rechercher les troubles du rythme cardiaque.', 'Pendant la montée du cathéter dans les cavités cardiaques, surveiller le rythme en continu pour dépister les troubles du rythme.'),
  ('securisation_proc', array['sections','0','items','15','rows','31','1']::text[], 'Le dégonflement du ballonnet doit être systématiquement vérifié après que ce dernier a été utilisé.', 'Toujours contrôler le dégonflement du ballonnet après son utilisation.'),
  ('securisation_proc', array['sections','0','items','15','rows','33','1']::text[], 'Le cathéter artériel pulmonaire doit être maintenu en place le moins longtemps possible ; une durée maximale de trois jours est conseillée.', 'Laisser le cathéter artériel pulmonaire en place le moins longtemps possible, trois jours au plus.'),
  ('securisation_proc', array['sections','0','items','17','rows','6','1']::text[], 'La pose et l''entretien des cathéters doivent être conformes aux recommandations du CLIN concernant la prévention du risque infectieux au cours de la mise en place des cathéters veineux centraux.', 'Poser et entretenir les cathéters selon les recommandations du CLIN sur la prévention du risque infectieux lors de la pose des cathéters veineux centraux.'),
  ('securisation_proc', array['sections','0','items','19','rows','4','1']::text[], 'Les lignes de perfusion artérielle doivent toujours être raccordées à une tête de pression.', 'Toute ligne de perfusion artérielle est reliée en permanence à une tête de pression.'),
  ('securisation_proc', array['sections','0','items','19','rows','8','1']::text[], 'Tout pôle de réanimation pédiatrique doit être équipé de masques de ventilation manuelle adaptés à la taille de l''enfant.', 'Chaque pôle de réanimation pédiatrique dispose de masques de ventilation manuelle adaptés à toutes les tailles d''enfant.'),
  ('securisation_proc', array['sections','0','items','19','rows','9','1']::text[], 'Tout service de réanimation pédiatrique doit pouvoir réaliser des épurations extra-rénales.', 'Chaque réanimation pédiatrique doit être en mesure de pratiquer une épuration extrarénale.'),
  ('securisation_proc', array['sections','0','items','22','rows','3','1']::text[], 'Lorsqu''il est réalisé une déplétion chez un patient à risque, il est nécessaire de mettre en place un monitorage de la précharge ventriculaire adapté aux conditions du patient.', 'Chez un patient à risque, toute déplétion impose un monitorage de la précharge ventriculaire adapté à sa situation.'),
  ('sevrage_vm', array['sections','1','items','2','rows','2','1']::text[], 'FiO2 ≤ 50 % et niveau de PEP ≤ 5 cmH2O <i>[c, 3]</i>. Le médecin peut s''affranchir d''un ou plusieurs de ces critères (généraux ou respiratoires) pour décider de l''épreuve de VS <i>[3]</i>.', 'FiO2 ≤ 50 % et PEP ≤ 5 cmH2O <i>[c, 3]</i>. Le médecin peut décider d''une épreuve de VS sans réunir tous ces critères, généraux ou respiratoires <i>[3]</i>.'),
  ('traumatisme_cranien_leger', array['sections','2','items','3','rows','1','1']::text[], 'Otorrhée ou rhinorrhée, ecchymose mastoïdienne, ecchymose périorbitaire, hémotympan ou saignement extériorisé par le conduit auditif', 'Otorrhée, rhinorrhée, ecchymose mastoïdienne ou périorbitaire, hémotympan, saignement par le conduit auditif'),
  ('traumatisme_cranien_leger', array['sections','2','items','3','rows','2','1']::text[], 'Discontinuité palpable de la voûte, suspicion d''embarrure ouverte ou fermée du crâne', 'Discontinuité de la voûte à la palpation, suspicion d''embarrure crânienne ouverte ou fermée'),
  ('traumatisme_cranien_leger', array['sections','3','items','1','rows','2','1']::text[], 'Les experts proposent de réaliser, après un scanner cérébral anormal, un Doppler Transcrânien chez les patients traumatisés crâniens légers pour évaluer le risque d''aggravation neurologique précoce.', 'Les experts proposent, chez le traumatisé crânien léger dont le scanner cérébral est anormal, un Doppler transcrânien pour apprécier le risque d''aggravation neurologique précoce.'),
  ('traumatisme_cranien_leger', array['sections','6','items','1','rows','2','1']::text[], 'Les experts proposent que les patients présentant un TCL traité en ambulatoire, et le cas échéant leur entourage, bénéficient d''une information éclairée écrite et orale standardisée sur les motifs devant amener à reconsulter aux urgences dans les 48 heures suivant le retour à domicile.', 'Les experts proposent de remettre au patient ayant un TCL pris en charge en ambulatoire, et à ses proches si besoin, une information standardisée, orale et écrite, sur les signes devant conduire à reconsulter aux urgences dans les 48 heures après le retour à domicile.'),
  ('urgences_transfusionnelles_obstetricales', array['sections','4','items','7','rows','1','0']::text[], 'Les différents acteurs intervenants : qui prescrit et qui pose l''indication de la transfusion', 'Rôle de chacun : qui prescrit la transfusion et qui en pose l''indication'),
  ('urgences_transfusionnelles_obstetricales', array['sections','4','items','7','rows','11','0']::text[], 'Modalités de l''acte transfusionnel lui-même : vérification des documents, contrôle ultime pré-transfusionnel…', 'Déroulement de l''acte transfusionnel : vérification des documents, contrôle ultime prétransfusionnel…'),
  ('urgences_transfusionnelles_obstetricales', array['sections','4','items','7','rows','15','0']::text[], 'L''évaluation régulière des procédures mises en place (essentiellement pour l''urgence vitale), leur pertinence et leur efficacité', 'Évaluation régulière des procédures (surtout pour l''urgence vitale) : pertinence et efficacité'),
  ('aap_urgence', array['sections','1','items','1','rows','4','1']::text[], 'Ne pas administrer de rFVIIa pour neutraliser le clopidogrel ou le prasugrel.', 'Le rFVIIa n''est pas indiqué pour neutraliser le clopidogrel ou le prasugrel.'),
  ('aap_urgence', array['sections','1','items','1','rows','6','1']::text[], 'Administrer de l''acide tranexamique pour son efficacité à réduire le saignement, que le patient soit ou non traité par AAP.', 'L''acide tranexamique réduit le saignement : l''administrer, que le patient reçoive ou non des AAP.'),
  ('aap_urgence', array['sections','3','items','2','rows','5','1']::text[], 'Neutraliser le traitement antiplaquettaire en cas de persistance de l''hémorragie après échec des traitements étiologiques et symptomatiques.', 'Si l''hémorragie persiste malgré les traitements étiologiques et symptomatiques, neutraliser le traitement antiplaquettaire.'),
  ('traumatisme_cranien', array['sections','1','items','1','rows','3','1']::text[], 'Chez un patient victime de TC grave nécessitant une craniotomie en urgence, il est probablement recommandé de considérer les indices de fragilité pathologiques pour évaluer le pronostic, mais pas de manière isolée pour contre-indiquer le geste.', 'Probablement recommandé : chez le traumatisé crânien grave nécessitant une craniotomie urgente, tenir compte des indices de fragilité pour le pronostic, mais pas pour récuser à eux seuls l''intervention.'),
  ('tracheotomie', array['sections','0','items','4','rows','2','1']::text[], 'Les experts suggèrent que l''indication de la trachéotomie chez les patients ayant une insuffisance respiratoire chronique fasse l''objet d''une concertation multidisciplinaire.', 'Selon les experts, l''indication de trachéotomie chez l''insuffisant respiratoire chronique devrait être discutée en concertation multidisciplinaire.'),
  ('tracheotomie', array['sections','1','items','1','rows','2','1']::text[], 'Les experts suggèrent qu''une concertation médicochirurgicale décide de la technique de trachéotomie à utiliser en cas de situation à risque de complication.', 'Selon les experts, dans les situations à risque de complication, le choix de la technique de trachéotomie devrait être décidé en concertation médicochirurgicale.'),
  ('tracheotomie', array['sections','1','items','4','rows','1','1']::text[], 'Il faut probablement réaliser une fibroscopie avant et pendant la réalisation de la trachéotomie percutanée.', 'Une fibroscopie avant et pendant la trachéotomie percutanée est probablement nécessaire.'),
  ('tracheotomie', array['sections','1','items','4','rows','2','1']::text[], 'Il ne faut probablement pas recourir à la pose d''un masque laryngé pendant la réalisation de la trachéotomie percutanée en réanimation.', 'Il ne faut probablement pas poser de masque laryngé au cours d''une trachéotomie percutanée en réanimation.'),
  ('tracheotomie', array['sections','2','items','1','rows','2','1']::text[], 'Les experts suggèrent de réaliser une humidification des voies aériennes chez les patients ayant une trachéotomie en réanimation.', 'Selon les experts, humidifier les voies aériennes des patients trachéotomisés en réanimation.'),
  ('tracheotomie', array['sections','2','items','1','rows','3','1']::text[], 'Les experts suggèrent de ne pas changer la canule de trachéotomie de façon systématique en réanimation.', 'Selon les experts, pas de changement systématique de la canule de trachéotomie en réanimation.'),
  ('tracheotomie', array['sections','3','items','1','rows','1','1']::text[], 'Les experts suggèrent qu''un protocole multidisciplinaire de décanulation soit disponible dans les services de réanimation.', 'Selon les experts, chaque réanimation devrait disposer d''un protocole multidisciplinaire de décanulation.'),
  ('tracheotomie', array['sections','3','items','1','rows','2','1']::text[], 'Il faut probablement envisager de dégonfler le ballonnet de la canule de trachéotomie lorsque les patients sont en ventilation spontanée.', 'Il faut probablement envisager le dégonflage du ballonnet de canule chez le patient trachéotomisé en ventilation spontanée.'),
  ('eer', array['sections','1','items','1','rows','2','1']::text[], 'Il faut considérer les sites veineux fémoraux et jugulaires internes droits comme équivalents en termes de complications infectieuses.', 'Sur le plan infectieux, les voies fémorale et jugulaire interne droite sont à considérer comme équivalentes.'),
  ('eer', array['sections','1','items','1','rows','4','1']::text[], 'Il faut considérer les sites veineux fémoraux et jugulaires internes droits comme équivalents en termes de risque de dysfonction de cathéter.', 'Pour le risque de dysfonction du cathéter, les voies fémorale et jugulaire interne droite sont à considérer comme équivalentes.'),
  ('eer', array['sections','1','items','1','rows','5','1']::text[], 'Il faut probablement réserver le site jugulaire interne gauche comme troisième choix.', 'La voie jugulaire interne gauche est probablement à garder en troisième intention.'),
  ('eer', array['sections','1','items','4','rows','1','1']::text[], 'Il ne faut probablement pas utiliser de membranes en cellulose non modifiée (cuprophane) pour la prise en charge des patients en IRA.', 'Probablement à éviter dans l''IRA : les membranes en cellulose non modifiée (cuprophane) — il ne faut probablement pas les utiliser.'),
  ('eer', array['sections','4','items','1','rows','6','1']::text[], 'En hémodialyse intermittente prolongée à faible clairance (SLED), il faut utiliser des débits sang et dialysat inférieurs. (Avis d''experts)', 'En SLED (hémodialyse intermittente prolongée à faible clairance), les débits de sang et de dialysat sont plus bas. (Avis d''experts)'),
  ('eer', array['sections','4','items','1','rows','7','1']::text[], 'Il faut que le branchement des lignes artérielles et veineuses soit réalisé de façon simultanée pour éviter la déplétion volémique. (Avis d''experts)', 'Brancher simultanément les lignes artérielle et veineuse afin de prévenir une déplétion volémique. (Avis d''experts)'),
  ('eer', array['sections','4','items','1','rows','8','1']::text[], 'En hémodialyse intermittente, il faut probablement recommander la baisse de la température dans le dialysat pour améliorer la tolérance hémodynamique.', 'En hémodialyse intermittente, abaisser la température du dialysat améliore probablement la tolérance hémodynamique et doit probablement être recommandé.'),
  ('aap_programmee', array['sections','1','items','0','2','rows','1','1']::text[], 'Il est proposé de diviser le risque hémorragique associé à la procédure invasive en risque élevé, intermédiaire et faible.', 'Proposé : classer le risque hémorragique de la procédure invasive en trois niveaux : élevé, intermédiaire, faible.'),
  ('aap_programmee', array['sections','1','items','0','2','rows','2','1']::text[], 'Les procédures à risque hémorragique élevé sont définies comme non réalisables sous AAP, même sous aspirine en monothérapie. Ce sont celles pour lesquelles le risque hémorragique sous aspirine est soit inconnu mais considéré comme potentiellement préoccupant, soit inacceptable ou jugé comme tel (risque létal ou fonctionnel). Elles sont peu fréquentes et incluent, par exemple, certains actes d''urologie lorsque des techniques alternatives ne peuvent pas être utilisées, de nombreux actes de neurochirurgie intracrânienne, les chirurgies avec des délabrements importants ou de grandes dissections, certains actes de chirurgie hépatique ou thoracique.', 'Risque hémorragique élevé : procédures impossibles sous AAP, y compris sous aspirine seule, parce que le risque de saignement sous aspirine y est inconnu mais jugé potentiellement préoccupant, ou inacceptable, réellement ou par prudence (risque vital ou fonctionnel). Elles sont rares : par exemple certains gestes urologiques sans alternative technique, de nombreux gestes de neurochirurgie intracrânienne, les chirurgies très délabrantes ou avec larges dissections, certains gestes hépatiques ou thoraciques.'),
  ('aap_programmee', array['sections','1','items','0','2','rows','3','1']::text[], 'Les procédures à risque hémorragique intermédiaire sont définies comme réalisables sous aspirine seule. Il s''agit de la majorité des procédures invasives.', 'Risque hémorragique intermédiaire : procédures réalisables sous aspirine seule, soit la plupart des gestes invasifs.'),
  ('aap_programmee', array['sections','1','items','0','2','rows','5','1']::text[], 'Lorsqu''il n''existe pas de consensus ou de référentiel pour classer un acte invasif dans une de ces catégories, il est proposé qu''une équipe référente (opérateur, anesthésiste, cardiologue, pneumologue, médecin vasculaire, hémostasien…) dans l''établissement de santé définisse une attitude de prise en charge, au cas par cas, ou pour un profil de patient ou de geste. Ces décisions sont notifiées dans le dossier du patient ou dans les procédures de l''établissement.', 'Proposé : en l''absence de consensus ou de référentiel permettant de classer un geste, une équipe référente de l''établissement (opérateur, anesthésiste, cardiologue, pneumologue, médecin vasculaire, hémostasien…) arrête la conduite à tenir, au cas par cas ou par profil de patient ou de geste, et la consigne dans le dossier du patient ou dans les procédures internes.'),
  ('aap_programmee', array['sections','1','items','0','2','rows','6','1']::text[], 'Concernant les endoscopies digestives, il est proposé que des stratégies de gestion des AAP soient définies dans chaque centre en fonction du profil des patients pris en charge et donc du geste invasif pouvant être potentiellement réalisé pendant l''endoscopie. Ainsi, si la probabilité d''un geste nécessitant une interruption des AAP pour un profil de patient déterminé est jugée élevée, c''est cette stratégie qui est adoptée (ex. : sphinctérotomie, gastrostomie…). En revanche, si la probabilité est faible, c''est la poursuite des AAP qui est privilégiée (ex. : maladies inflammatoires chroniques de l''intestin, dyspepsie…). Quand la probabilité et la nature des lésions à réséquer n''est pas connue a priori, chaque centre détermine son attitude (ex. : recherche de polypes).', 'Proposé, pour les endoscopies digestives : chaque centre définit sa gestion des AAP selon le profil de ses patients et les gestes susceptibles d''être réalisés. Si un geste imposant l''arrêt des AAP est probable pour un profil donné (sphinctérotomie, gastrostomie…), on arrête ; s''il est peu probable (maladies inflammatoires chroniques de l''intestin, dyspepsie…), on poursuit. Lorsque la probabilité et la nature des lésions à réséquer ne sont pas connues à l''avance (recherche de polypes par exemple), chaque centre fixe sa propre conduite.'),
  ('aap_programmee', array['sections','3','items','0','2','rows','2','1']::text[], 'Il est recommandé de n''utiliser ni les héparines (HNF ou HBPM) ni les AINS en relais des AAP.', 'Recommandé : pas de relais des AAP par héparines (HNF ou HBPM) ni par AINS.'),
  ('aap_programmee', array['sections','3','items','0','2','rows','3','1']::text[], 'Chez les patients traités au long cours par aspirine à des posologies allant jusqu''à 300 mg/j, il est proposé de ne pas réduire la posologie en vue de la chirurgie.', 'Proposé : chez le patient sous aspirine au long cours jusqu''à 300 mg/j, ne pas diminuer la dose avant la chirurgie.'),
  ('aap_programmee', array['sections','3','items','3','2','rows','1','1']::text[], 'Il est proposé de ne pas initier un traitement par aspirine en préopératoire d''une chirurgie non cardiaque (à l''exception de l''endartériectomie carotidienne) dans le but de réduire les évènements cardiovasculaires périopératoires.', 'Proposé : ne pas débuter d''aspirine avant une chirurgie non cardiaque (sauf endartériectomie carotidienne) dans le but de prévenir les événements cardiovasculaires périopératoires.'),
  ('aap_programmee', array['sections','3','items','3','2','rows','2','1']::text[], 'Il est proposé d''arrêter l''aspirine en préopératoire lorsqu''elle est prescrite en prévention primaire.', 'Proposé : interrompre avant l''intervention une aspirine prescrite en prévention primaire.'),
  ('aap_programmee', array['sections','3','items','3','2','rows','3','1']::text[], 'Il est proposé de ne pas arrêter l''aspirine en préopératoire lorsqu''elle est prescrite en prévention cardiovasculaire secondaire (post-accident vasculaire cérébral ischémique, coronaropathie, artériopathie des membres inférieurs), à l''exception des procédures à risque hémorragique élevé.', 'Proposé : ne pas interrompre avant l''intervention une aspirine prescrite en prévention cardiovasculaire secondaire (après AVC ischémique, coronaropathie, artériopathie des membres inférieurs), sauf procédure à risque hémorragique élevé.'),
  ('aap_programmee', array['sections','3','items','3','2','rows','5','1']::text[], 'Il est proposé que la reprise de l''AAP soit aussi précoce que possible, en fonction du risque de saignement postopératoire, chez les patients ayant une indication à un traitement par AAP en monothérapie au long cours.', 'Proposé : chez le patient relevant d''une monothérapie antiplaquettaire au long cours, reprendre l''AAP le plus tôt possible selon le risque de saignement postopératoire.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','1','1']::text[], 'Il est proposé que la gestion préopératoire des AAP et leur reprise postopératoire soit discutée avec le cardiologue du patient ou un cardiologue référent et tracée dans le dossier lorsqu''il s''agit d''une procédure à risque hémorragique intermédiaire ou élevé.', 'Proposé : pour une procédure à risque hémorragique intermédiaire ou élevé, discuter l''arrêt et la reprise des AAP avec le cardiologue du patient ou un cardiologue référent, et le tracer dans le dossier.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','2','1']::text[], 'Il est proposé de reporter toute chirurgie non cardiaque à la fin de la durée recommandée de la bithérapie antiplaquettaire quand cela ne génère pas de risque vital ou fonctionnel majeur pour le patient.', 'Proposé : différer toute chirurgie non cardiaque jusqu''au terme de la bithérapie antiplaquettaire recommandée, si ce délai n''expose pas le patient à un risque vital ou fonctionnel majeur.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','3','1']::text[], 'Si ce report n''est pas possible, il est proposé de repousser toute chirurgie non cardiaque au-delà du 1er mois qui suit la pose de stent, quel que soit le type de stent, quelle que soit l''indication (IDM ou coronaropathie stable). Si le geste ne peut être différé au-delà du 1er mois, il est proposé de réaliser cette chirurgie en poursuivant l''aspirine et dans un centre ayant un plateau de cardiologie interventionnelle actif 24 heures sur 24.', 'Proposé, si ce report est impossible : repousser toute chirurgie non cardiaque au-delà du 1er mois après la pose du stent, quels que soient le type de stent et l''indication (IDM ou coronaropathie stable). Si l''intervention ne peut attendre la fin du 1er mois, l''effectuer sous aspirine, dans un centre disposant d''une cardiologie interventionnelle opérationnelle 24 heures sur 24.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','4','1']::text[], 'Chez les patients sous bithérapie antiplaquettaire dans les suites d''un IDM ou en cas de pose de stent associé à des caractéristiques à haut risque thrombotique, il est proposé de reporter toute chirurgie non cardiaque au-delà du 6e mois qui suit la pose de stent.', 'Proposé : sous bithérapie antiplaquettaire après un IDM, ou après pose de stent avec critères de haut risque thrombotique, repousser toute chirurgie non cardiaque au-delà du 6e mois suivant la pose du stent.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','5','1']::text[], 'Il est recommandé de poursuivre l''aspirine en préopératoire. Si elle a été interrompue, il est recommandé de la reprendre aussi précocement que possible après la procédure invasive, au mieux le jour même, en fonction du risque de saignement postopératoire.', 'Recommandé : maintenir l''aspirine avant l''intervention. En cas d''interruption, la reprendre au plus tôt après la procédure, idéalement le jour même, selon le risque hémorragique postopératoire (recommandé).'),
  ('aap_programmee', array['sections','4','items','0','2','rows','6','1']::text[], 'Si les deux AAP doivent être interrompus dans le 1er mois suivant la pose de stent, un relais par des AAP parentéraux réversibles comme le tirofiban ou le cangrélor peut être discuté au cas par cas, avec une approche multidisciplinaire (utilisation hors AMM). Dans ces situations exceptionnelles, associées à un haut risque hémorragique et thrombotique, le relais doit être réalisé en soins intensifs et la chirurgie doit être réalisée dans un centre ayant un service de cardiologie interventionnelle actif 24 heures sur 24.', 'Lorsque les deux AAP doivent être arrêtés durant le 1er mois après la pose du stent, un relais par AAP parentéraux réversibles (tirofiban, cangrélor ; hors AMM) peut se discuter au cas par cas en équipe multidisciplinaire. Dans ces situations exceptionnelles, à haut risque hémorragique et thrombotique, le relais a lieu en soins intensifs et l''intervention dans un centre doté d''une cardiologie interventionnelle opérationnelle 24 heures sur 24.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','7','1']::text[], 'Si les anti-P2Y12 ont été interrompus avant la chirurgie, ils doivent être repris précocement, au mieux dans les 24 à 72 heures après la chirurgie, compte tenu de l''augmentation du risque thrombotique. La reprise se fait avec le même anti-P2Y12 qu''en préopératoire.', 'Les anti-P2Y12 interrompus avant l''intervention sont à reprendre tôt, idéalement 24 à 72 heures après, du fait du risque thrombotique accru, en utilisant la même molécule qu''avant l''intervention.'),
  ('aap_programmee', array['sections','4','items','0','2','rows','8','1']::text[], 'Il est proposé de ne pas administrer d''AINS en périopératoire chez les patients traités par bithérapie antiplaquettaire.', 'Proposé : pas d''AINS en périopératoire chez le patient sous bithérapie antiplaquettaire.'),
  ('aap_programmee', array['sections','5','items','0','2','rows','1','1']::text[], 'L''aspirine ne contre-indique pas une ALR rachidienne si le rapport bénéfice-risque est favorable, en vérifiant l''absence d''anomalie associée de l''hémostase, incluant un traitement anticoagulant. Il est proposé de préférer si possible la rachianesthésie en ponction unique à la péridurale.', 'L''aspirine n''interdit pas une ALR rachidienne lorsque le bénéfice l''emporte sur le risque, sous réserve qu''aucune autre anomalie de l''hémostase (traitement anticoagulant compris) ne s''y ajoute. Proposé : préférer si possible une rachianesthésie en injection unique à une péridurale.'),
  ('aap_programmee', array['sections','5','items','0','2','rows','2','1']::text[], 'L''ALR rachidienne est contre-indiquée en cas de traitement par anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), sauf si ces AAP ont été interrompus respectivement 5, 7 et 5 jours avant le geste.', 'Sous anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), l''ALR rachidienne est contre-indiquée, sauf arrêt respectivement 5, 7 et 5 jours avant le geste.'),
  ('aap_programmee', array['sections','5','items','0','2','rows','3','1']::text[], 'La mise en place d''un cathéter péridural expose à une gestion complexe des AAP. Le retrait du cathéter suit les mêmes règles que la pose. Le recours au cathéter péridural ne doit pas compromettre la reprise postopératoire des AAP, et en particulier des anti-P2Y12.', 'Un cathéter péridural complique la gestion des AAP. Son retrait obéit aux mêmes règles que sa pose, et il ne doit pas retarder la reprise des AAP après l''intervention, notamment des anti-P2Y12.'),
  ('aap_programmee', array['sections','5','items','3','rows','2','1']::text[], 'Il est proposé que les blocs nerveux périphériques à haut risque hémorragique puissent être réalisés sous aspirine en monothérapie si le rapport bénéfice/risque est favorable. Ces blocs sont contre-indiqués sous anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), sauf si ces AAP ont été interrompus respectivement 5, 7 et 5 jours avant le geste.', 'Proposé : les blocs nerveux périphériques à haut risque hémorragique peuvent être faits sous aspirine seule si le bénéfice l''emporte sur le risque. Sous anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), ils sont contre-indiqués, sauf arrêt respectivement 5, 7 et 5 jours avant le geste.'),
  ('aap_programmee', array['sections','5','items','3','rows','3','1']::text[], 'Il est proposé que ces blocs (superficiels ou profonds) soient réalisés par échoguidage et par un opérateur expérimenté.', 'Proposé : réaliser ces blocs, superficiels ou profonds, sous échoguidage par un opérateur entraîné.'),
  ('aap_programmee', array['sections','5','items','3','rows','4','1']::text[], 'La mise en place d''un cathéter périnerveux ne doit pas compromettre la reprise postopératoire des AAP, et en particulier des anti-P2Y12. Son retrait suit les mêmes règles que la pose.', 'Un cathéter périnerveux ne doit pas retarder la reprise des AAP après l''intervention, notamment des anti-P2Y12 ; son retrait obéit aux mêmes règles que sa pose.'),
  ('aap_programmee', array['sections','6','items','0','2','rows','1','1']::text[], 'Il est proposé que la stratégie de gestion des AAP en vue de pontage aortocoronaire (PAC) soit décidée de façon multidisciplinaire en fonction du risque hémorragique et du risque thrombotique de chaque patient.', 'Proposé : avant un pontage aortocoronaire (PAC), décider en équipe multidisciplinaire de la gestion des AAP selon les risques hémorragique et thrombotique propres au patient.'),
  ('aap_programmee', array['sections','6','items','0','2','rows','2','1']::text[], 'Il est proposé de poursuivre l''aspirine pour la chirurgie de PAC.', 'Proposé : maintenir l''aspirine pour un PAC.'),
  ('aap_programmee', array['sections','6','items','0','2','rows','4','1']::text[], 'Des données récentes suggèrent que la chirurgie semi-urgente puisse être réalisée après une interruption plus courte du ticagrélor, de 3 à 5 jours, sans surrisque hémorragique pour la majorité des patients. Cependant, dans cette situation, les patients n''ayant pas une correction de l''inhibition plaquettaire induite par le ticagrélor sont exposés à un risque d''hémorragie.', 'Selon des données récentes, une chirurgie semi-urgente pourrait se faire après un arrêt plus bref du ticagrélor (3 à 5 jours) sans surcroît de saignement chez la plupart des patients. Ceux dont l''inhibition plaquettaire sous ticagrélor n''est pas corrigée restent toutefois exposés à un risque hémorragique.'),
  ('mtev_perioperatoire', array['sections','4','items','0','2','rows','4','1']::text[], 'Il est proposé de prescrire une thromboprophylaxie par HBPM pour une durée minimale de 7 jours.', 'Proposé : thromboprophylaxie par HBPM pendant au moins 7 jours.'),
  ('mtev_perioperatoire', array['sections','4','items','4','2','rows','1','1']::text[], 'Après chirurgie carotidienne, il est proposé de ne pas prescrire de thromboprophylaxie veineuse systématique.', 'Proposé : pas de thromboprophylaxie veineuse systématique après chirurgie carotidienne.'),
  ('mtev_perioperatoire', array['sections','6','items','1','2','rows','1','1']::text[], 'Les contentions élastiques graduées ne sont pas recommandées pour la thromboprophylaxie péri-opératoire, quel que soit le risque thromboembolique veineux.', 'Quel que soit le risque thromboembolique veineux, les bas de contention élastique gradués ne sont pas recommandés pour la thromboprophylaxie périopératoire.'),
  ('controle_temperature', array['sections','1','items','1','rows','3','1']::text[], 'Chez les patients comateux après réanimation d''un AC intra-hospitalier, il faut probablement pratiquer un CCT dans le but d''améliorer la survie avec bon pronostic neurologique.', 'Il faut probablement un CCT chez le patient resté comateux après réanimation d''un AC intrahospitalier, afin d''accroître la survie avec un bon pronostic neurologique.'),
  ('controle_temperature', array['sections','1','items','1','rows','5','1']::text[], 'Parmi les méthodes de CCT disponibles en préhospitalier, chez les patients traités par CCT après AC, il ne faut probablement pas débuter le CCT par perfusion de solutés froids pendant le transport vers l''hôpital, dans le but d''améliorer la survie avec bon pronostic neurologique.', 'Chez le patient traité par CCT après AC, il ne faut probablement pas commencer le CCT en préhospitalier par la perfusion de solutés froids durant le transport, cette méthode n''améliorant pas la survie avec un bon pronostic neurologique.'),
  ('controle_temperature', array['sections','1','items','1','rows','6','1']::text[], '<i>(Pédiatrique)</i> Chez les enfants comateux après réanimation d''un AC intra- ou extra-hospitalier sur rythme non choquable ou choquable, il faut probablement effectuer un CCT avec pour objectif la normothermie pour améliorer le pronostic neurologique.', '<i>(Pédiatrique)</i> Chez l''enfant resté comateux après réanimation d''un AC intra- ou extrahospitalier, sur rythme choquable ou non, il faut probablement un CCT visant la normothermie pour améliorer le pronostic neurologique.'),
  ('controle_temperature', array['sections','1','items','3','rows','4','1']::text[], '<i>(Pédiatrique)</i> Chez l''enfant traumatisé crânien grave, il faut faire un CCT visant à maintenir une normothermie.', '<i>(Pédiatrique)</i> Il faut un CCT chez l''enfant traumatisé crânien grave, avec pour cible la normothermie.'),
  ('controle_temperature', array['sections','2','items','1','rows','1','1']::text[], 'Chez les patients à la phase aiguë d''un AVC ischémique grave, il faut probablement pratiquer un CCT ciblant la normothermie.', 'Il faut probablement un CCT visant la normothermie à la phase aiguë d''un AVC ischémique grave.'),
  ('controle_temperature', array['sections','2','items','3','rows','2','1']::text[], 'Chez les patients dans le coma avec une méningite ou une méningo-encéphalite, il ne faut probablement pas pratiquer de CCT lorsque la fièvre est bien tolérée.', 'Il ne faut probablement pas de CCT chez le patient comateux atteint de méningite ou de méningo-encéphalite dont la fièvre est bien tolérée.'),
  ('controle_temperature', array['sections','2','items','3','rows','4','1']::text[], 'Chez les patients dans le coma avec une méningite bactérienne et une HTIC, il faut probablement pratiquer une hypothermie, en comparaison avec une normothermie, dans le but d''améliorer la survie avec bon pronostic neurologique.', 'Chez le patient comateux atteint de méningite bactérienne avec HTIC, il faut probablement préférer l''hypothermie à la normothermie pour améliorer la survie avec un bon pronostic neurologique.'),
  ('controle_temperature', array['sections','2','items','3','rows','5','1']::text[], '<i>(Pédiatrique)</i> Chez l''enfant présentant un état de mal épileptique, il faut probablement réaliser un CCT (normothermie) à visée neuroprotectrice.', '<i>(Pédiatrique)</i> Il faut probablement un CCT (normothermie) à visée neuroprotectrice chez l''enfant en état de mal épileptique.'),
  ('controle_temperature', array['sections','3','items','1','rows','3','1']::text[], 'Chez les patients en choc septique, il faut probablement pratiquer un CCT ciblant la normothermie dans le but d''améliorer l''hémodynamique.', 'Il faut probablement un CCT visant la normothermie au cours du choc septique, pour améliorer l''hémodynamique.'),
  ('controle_temperature', array['sections','3','items','3','rows','1','1']::text[], 'Chez les patients traités par CCT, il faut utiliser des méthodes asservies à la température corporelle, par comparaison aux méthodes non asservies, dans le but d''améliorer la qualité du CCT.', 'Il faut utiliser, pour un CCT de meilleure qualité, des dispositifs asservis à la température corporelle plutôt que non asservis.'),
  ('controle_temperature', array['sections','3','items','3','rows','2','1']::text[], 'Chez les patients traités par CCT, il faut probablement contrôler la vitesse du réchauffement.', 'Il faut probablement maîtriser la vitesse de réchauffement au cours du CCT.'),
  ('controle_temperature', array['sections','3','items','3','rows','3','1']::text[], 'Chez les patients traités par CCT, il faut probablement privilégier des sites de mesure de température centrale.', 'Il faut probablement préférer une mesure centrale de la température au cours du CCT.'),
  ('controle_temperature', array['sections','3','items','3','rows','4','1']::text[], 'Chez les patients traités par CCT, il faut probablement surveiller la survenue de certaines complications : sepsis, pneumopathie, arythmie, hypokaliémie.', 'Il faut probablement surveiller, au cours du CCT, certaines complications : sepsis, pneumopathie, arythmie, hypokaliémie.'),
  ('controle_temperature', array['sections','3','items','3','rows','5','1']::text[], '<i>(Pédiatrique)</i> Chez les enfants pour lesquels le CCT a été retenu, il faut probablement utiliser des méthodes asservies à la température corporelle, par comparaison aux méthodes non asservies, dans le but d''améliorer la qualité du CCT.', '<i>(Pédiatrique)</i> Il faut probablement utiliser, chez l''enfant relevant d''un CCT, des dispositifs asservis à la température corporelle plutôt que non asservis, pour un CCT de meilleure qualité.'),
  ('controle_temperature', array['sections','3','items','3','rows','6','1']::text[], '<i>(Pédiatrique)</i> Chez les enfants traités par CCT, il faut probablement privilégier des sites de mesure de température centrale.', '<i>(Pédiatrique)</i> Il faut probablement préférer une mesure centrale de la température chez l''enfant traité par CCT.'),
  ('douleur_postoperatoire', array['sections','3','items','3','rows','5','0']::text[], 'Infiltrer la cicatrice de thyroïdectomie avec des anesthésiques locaux à longue durée d''action.', 'Infiltrer la cicatrice de thyroïdectomie par un anesthésique local de longue durée d''action.'),
  ('optimisation_beta_lactamines_2018', array['sections','0','items','3','rows','1','1']::text[], 'Tenir systématiquement et quotidiennement compte des nombreuses sources de variabilité pharmacocinétique lors de la prescription de bêta-lactamines.', 'Lors de toute prescription de bêta-lactamines, intégrer chaque jour les multiples facteurs de variabilité pharmacocinétique.'),
  ('chir_ambu_proctologie', array['sections','0','items','7','rows','1','1']::text[], 'Donner en préopératoire une information complète et détaillée sur la douleur postopératoire et sa prise en charge.', 'Informer le patient avant l''intervention, de façon complète et précise, sur la douleur postopératoire et son traitement.'),
  ('reduction_antibiotiques_reanimation_2014', array['sections','0','items','11','rows','3','1']::text[], 'Il ne faut pas prescrire de FQ de façon répétée chez un même patient (prendre en compte les prescriptions antérieures de FQ dans les 6 mois précédents, quelle qu''en soit l''indication).', 'Il ne faut pas répéter les prescriptions de FQ chez un même patient : tenir compte de toute FQ reçue dans les 6 mois précédents, quelle qu''en soit l''indication.'),
  ('reduction_antibiotiques_reanimation_2014', array['sections','0','items','11','rows','4','1']::text[], 'Il ne faut pas prescrire en probabiliste de FQ en monothérapie dans les infections nosocomiales sévères.', 'Il ne faut pas de FQ seule en traitement probabiliste d''une infection nosocomiale sévère.'),
  ('simulation_soins_critiques_2019', array['sections','0','items','3','rows','5','1']::text[], 'Ne pas utiliser la simulation comme méthode pédagogique unique, sans intégration à un curriculum de formation.', 'Ne pas recourir à la simulation comme seule méthode pédagogique, hors de tout curriculum de formation.'),
  ('simulation_soins_critiques_2019', array['sections','0','items','6','rows','3','1']::text[], 'Utiliser la simulation haute fidélité pour améliorer le travail en équipe pluri-professionnel dans la gestion de crises en soins critiques.', 'Recourir à la simulation haute fidélité pour renforcer le travail d''équipe pluriprofessionnel lors des crises en soins critiques.'),
  ('simulation_soins_critiques_2019', array['sections','0','items','6','rows','4','1']::text[], 'Utiliser la simulation pour améliorer les compétences en communication entre professionnels en soins critiques, en formation initiale et continue, médicale et paramédicale.', 'Recourir à la simulation pour développer la communication entre professionnels de soins critiques, en formation initiale et continue, médicale et paramédicale.'),
  ('simulation_soins_critiques_2019', array['sections','0','items','7','rows','5','1']::text[], 'Utiliser la simulation pluri-professionnelle ou inter-professionnelle pour développer les compétences non techniques en soins critiques.', 'Recourir à la simulation pluri- ou interprofessionnelle pour développer les compétences non techniques en soins critiques.'),
  ('simulation_soins_critiques_2019', array['sections','0','items','9','rows','1','1']::text[], 'Utiliser la simulation pour acquérir les compétences nécessaires à la prise en charge des situations sanitaires exceptionnelles, sans qu''un outil particulier puisse être privilégié.', 'Recourir à la simulation pour se préparer aux situations sanitaires exceptionnelles, sans privilégier d''outil particulier.'),
  ('chir_ambu_urologie_2013', array['sections','0','items','3','rows','15','1']::text[], 'Il est recommandé de déterminer pour chaque intervention, de façon collégiale, une durée de surveillance postopératoire minimale requise.', 'Recommandé : fixer collégialement, pour chaque intervention, une durée minimale de surveillance postopératoire.'),
  ('chir_ambu_urologie_2013', array['sections','0','items','8','rows','2','1']::text[], 'Il est recommandé de maintenir un traitement alpha-bloquant en périopératoire, sauf contre-indication (chirurgie de la cataracte).', 'Recommandé : ne pas interrompre l''alpha-bloquant autour de l''intervention, sauf contre-indication (chirurgie de la cataracte).'),
  ('chir_ambu_urologie_2013', array['sections','0','items','8','rows','3','1']::text[], 'Il est recommandé de ne pas limiter les apports hydriques, car cela augmente le risque de déshydratation, de caillotage vésical et ralentit la reprise des mictions.', 'Recommandé : ne pas restreindre les boissons, la restriction exposant à la déshydratation et au caillotage vésical et retardant la reprise des mictions.'),
  ('chir_ambu_urologie_2013', array['sections','1','items','2','rows','5','1']::text[], 'En cas de colonisation urinaire non traitée, il est recommandé de reporter une chirurgie programmée de l''appareil urinaire.', 'Recommandé : différer une chirurgie programmée de l''appareil urinaire tant qu''une colonisation urinaire n''est pas traitée.'),
  ('chir_ambu_urologie_2013', array['sections','1','items','4','rows','3','1']::text[], 'Il est recommandé de donner au patient, en préopératoire, une information sur la douleur postopératoire et sa prise en charge.', 'Recommandé : informer le patient avant l''intervention sur la douleur postopératoire et son traitement.'),
  ('sedation_procedurale_2026', array['sections','0','items','5','rows','7','1']::text[], 'Les experts suggèrent de ne pas différer la sédation procédurale pour respecter le jeûne, dans un objectif de sécurité.', 'Selon les experts, ne pas retarder une sédation procédurale pour respecter le jeûne, la sécurité n''y gagnant pas.'),
  ('sedation_procedurale_2026', array['sections','0','items','6','rows','3','1']::text[], 'Maladie organique sévère sans menace vitale à court terme, avec limitation fonctionnelle.', 'Affection organique sévère, sans risque vital à court terme, entraînant une limitation fonctionnelle.'),
  ('sedation_procedurale_2026', array['sections','0','items','13','rows','5','1']::text[], 'Il est recommandé d''utiliser l''association kétamine-propofol en comparaison à la kétamine seule ou au propofol seul.', 'Recommandé : préférer l''association kétamine-propofol à la kétamine ou au propofol utilisés seuls.')
) as v(fiche_key, chemin, original_html, proposition_html)
join public.documents d on d.fiche_key = v.fiche_key
on conflict (fiche_key, chemin) do nothing;
